KG42.register("rules-80a582f4dbd4e7552f157b44",{"id":"25-p2p_ancillary_bidding::v141-c-R005","paper":"25-p2p_ancillary_bidding","record":{"rule_id":"v141-c-R005","mechanism_id":"v141-a-M01-p2p-cda","name":"Price-signal coordination","process_stage":"coordination","market_meaning":"Results of preceding bid/ask matching provide feedback for customers' ZIP bid/ask price adjustments. Scope: Customers' decentralized ZIP price decisions during the CDA Agreement Period. The successful CDA trading price provides the comparison reference for customers' subsequent ZIP bid/ask price decisions. Scope: ZIP price decisions for bids and asks remaining in the order book for time slot t. Condition: The last CDA matching was successfully made at price π_t. In this successful-matching branch, arrival of an ask conditions the downward ZIP revision of an eligible bid price toward the feed-in tariff reference. Scope: ZIP revisions of bid prices in order book t during the CDA Agreement Period. Condition: The last matching was successful and π_{b,t} \u003c= π_t at the corresponding test in the update sequence. In the unsuccessful-matching branch, arrival of an ask conditions downward ZIP revisions of ask prices toward the feed-in tariff reference. Scope: ZIP revisions of ask prices in order book t during the CDA Agreement Period. Condition: The last matching was unsuccessful. In this successful-matching branch, arrival of a bid conditions the downward ZIP revision of an eligible ask price toward the feed-in tariff reference. Scope: ZIP revisions of ask prices in order book t during the CDA Agreement Period. Condition: The last matching was successful and π_{s,t} >= π_t at the corresponding test in the update sequence. In the unsuccessful-matching branch, arrival of a bid conditions downward ZIP revisions of bid prices toward the feed-in tariff reference. Scope: ZIP revisions of bid prices in order book t during the CDA Agreement Period. Condition: The last matching was unsuccessful.","independence_rationale":"Relations governed by the approved function coordination.price_signal under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","bidding.supply","coordination.price_signal","matching.counterparties","pricing.local"],"E":[{"edge_id":"v141-c-R005-E001","source":"coordination.price_signal","target":"bidding.demand","type":"conditional_on","constraint_ids":["v141-c-R005-C005","v141-c-R005-C006"],"evidence_ids":["v141-b-g04-E04"]},{"edge_id":"v141-c-R005-E002","source":"coordination.price_signal","target":"bidding.supply","type":"conditional_on","constraint_ids":["v141-c-R005-C003","v141-c-R005-C004"],"evidence_ids":["v141-b-g04-E04"]},{"edge_id":"v141-c-R005-E003","source":"matching.counterparties","target":"coordination.price_signal","type":"links","constraint_ids":["v141-c-R005-C001"],"evidence_ids":["v141-b-g01-E15"]},{"edge_id":"v141-c-R005-E004","source":"pricing.local","target":"coordination.price_signal","type":"links","constraint_ids":["v141-c-R005-C002"],"evidence_ids":["v141-b-g04-E04"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Customers' decentralized ZIP price decisions during the CDA Agreement Period. | ZIP price decisions for bids and asks remaining in the order book for time slot t. | ZIP revisions of ask prices in order book t during the CDA Agreement Period. | ZIP revisions of bid prices in order book t during the CDA Agreement Period.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E15","v141-b-g04-E04"]},"x":[{"variable_id":"v141-c-R005-x-pi-b","symbol":"π_{b,t}","meaning":"price of bid order o_{b,t} in the time-slot t order book, dynamically adjusted by the ZIP bidding process","kind":"operational","domain":"real-valued price in GBP/kWh for a demand bid in order book t; the source's ZIP budget constrains initial and adjusted bid prices","unit":"£/kWh","indices":["b","t"],"evidence_ids":["v141-b-g01-E05","v141-b-g04-E04"]},{"variable_id":"v141-c-R005-x-pi-s","symbol":"π_{s,t}","meaning":"price of ask order o_{s,t} in the time-slot t order book, dynamically adjusted by the ZIP bidding process","kind":"operational","domain":"real-valued price in GBP/kWh for a supply ask in order book t; the source's ZIP budget constrains initial and adjusted ask prices","unit":"£/kWh","indices":["s","t"],"evidence_ids":["v141-b-g01-E05","v141-b-g04-E04"]}],"theta":[{"parameter_id":"v141-c-R005-theta-gamma","symbol":"γ","meaning":"coefficient for customers to update bid/ask prices; source states its value is within (0,1)","value":{"kind":"text","number_value":null,"text_value":"within (0, 1)"},"unit":null,"indices":[],"evidence_ids":["v141-b-g04-E04"]},{"parameter_id":"v141-c-R005-theta-p-fit","symbol":"p_t^{FiT}","meaning":"feed-in tariff rate offered by the power utility for time slot t; lower reference in downward ZIP bid/ask revisions","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"£/kWh","indices":["t"],"evidence_ids":["v141-b-g04-E04"]},{"parameter_id":"v141-c-R005-theta-pi-t","symbol":"π_t","meaning":"price at which the last CDA matching was successfully made; comparison reference in the ZIP update tests","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"£/kWh","indices":["t"],"evidence_ids":["v141-b-g04-E04"]}],"phi":[{"constraint_id":"v141-c-R005-C001","kind":"procedural","role":"core","statement":"Results of preceding bid/ask matching provide feedback for customers' ZIP bid/ask price adjustments. Scope: Customers' decentralized ZIP price decisions during the CDA Agreement Period.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["matching.counterparties","coordination.price_signal"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E15"]},{"constraint_id":"v141-c-R005-C002","kind":"procedural","role":"core","statement":"The successful CDA trading price provides the comparison reference for customers' subsequent ZIP bid/ask price decisions. Scope: ZIP price decisions for bids and asks remaining in the order book for time slot t. Condition: The last CDA matching was successfully made at price π_t.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","coordination.price_signal"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g04-E04"]},{"constraint_id":"v141-c-R005-C003","kind":"logical","role":"core","statement":"In this successful-matching branch, arrival of an ask conditions the downward ZIP revision of an eligible bid price toward the feed-in tariff reference. Scope: ZIP revisions of bid prices in order book t during the CDA Agreement Period. Condition: The last matching was successful and π_{b,t} \u003c= π_t at the corresponding test in the update sequence.","expression":"∀ o_{b,t} in order book t: (last matching successful at π_t ∧ an ask arrived ∧ π_{b,t} ≤ π_t) ⇒ π_{b,t} ← π_{b,t} − γ·(π_{b,t} − p_t^{FiT})","formalization_origin":"source","template_id":null,"members":["coordination.price_signal","bidding.supply"],"variable_refs":["v141-c-R005-x-pi-b"],"parameter_refs":["v141-c-R005-theta-gamma","v141-c-R005-theta-p-fit","v141-c-R005-theta-pi-t"],"evidence_ids":["v141-b-g04-E04"]},{"constraint_id":"v141-c-R005-C004","kind":"logical","role":"core","statement":"In the unsuccessful-matching branch, arrival of an ask conditions downward ZIP revisions of ask prices toward the feed-in tariff reference. Scope: ZIP revisions of ask prices in order book t during the CDA Agreement Period. Condition: The last matching was unsuccessful.","expression":"∀ o_{s,t} in order book t: (last matching unsuccessful ∧ an ask arrived) ⇒ π_{s,t} ← π_{s,t} − γ·(π_{s,t} − p_t^{FiT})","formalization_origin":"source","template_id":null,"members":["coordination.price_signal","bidding.supply"],"variable_refs":["v141-c-R005-x-pi-s"],"parameter_refs":["v141-c-R005-theta-gamma","v141-c-R005-theta-p-fit"],"evidence_ids":["v141-b-g04-E04"]},{"constraint_id":"v141-c-R005-C005","kind":"logical","role":"core","statement":"In this successful-matching branch, arrival of a bid conditions the downward ZIP revision of an eligible ask price toward the feed-in tariff reference. Scope: ZIP revisions of ask prices in order book t during the CDA Agreement Period. Condition: The last matching was successful and π_{s,t} >= π_t at the corresponding test in the update sequence.","expression":"∀ o_{s,t} in order book t: (last matching successful at π_t ∧ a bid arrived ∧ π_{s,t} ≥ π_t) ⇒ π_{s,t} ← π_{s,t} − γ·(π_{s,t} − p_t^{FiT})","formalization_origin":"source","template_id":null,"members":["coordination.price_signal","bidding.demand"],"variable_refs":["v141-c-R005-x-pi-s"],"parameter_refs":["v141-c-R005-theta-gamma","v141-c-R005-theta-p-fit","v141-c-R005-theta-pi-t"],"evidence_ids":["v141-b-g04-E04"]},{"constraint_id":"v141-c-R005-C006","kind":"logical","role":"core","statement":"In the unsuccessful-matching branch, arrival of a bid conditions downward ZIP revisions of bid prices toward the feed-in tariff reference. Scope: ZIP revisions of bid prices in order book t during the CDA Agreement Period. Condition: The last matching was unsuccessful.","expression":"∀ o_{b,t} in order book t: (last matching unsuccessful ∧ a bid arrived) ⇒ π_{b,t} ← π_{b,t} − γ·(π_{b,t} − p_t^{FiT})","formalization_origin":"source","template_id":null,"members":["coordination.price_signal","bidding.demand"],"variable_refs":["v141-c-R005-x-pi-b"],"parameter_refs":["v141-c-R005-theta-gamma","v141-c-R005-theta-p-fit"],"evidence_ids":["v141-b-g04-E04"]}],"pi":[{"evidence_id":"v141-b-g01-E15","location":{"location_id":"src-212077b9a1-p05-c1r1__v141-a-M01-bidding","page":5,"printed_page":null,"section":null,"anchor_text":"Y. Zhou et al. > 0. Similarly, tothe amount of electricity to be bought being NL*i,t, if NL*i,t the ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"The bid/ask prices are assumed to be made given the assumption that the customers act as ‘zero intelligent plus (ZIP)’ traders [41]. The assumption of ZIP traders can well mimic the behaviors of human traders in stock markets. As a ZIP trader, each customer will set a budget constraint, [p_t^{FiT}, p_t^{retail}] to ensure that it will not be worse off by participating in the P2P energy trading compared to trading with the power utility. Initially, for each customer, the price for its bid/ask is decided uniformly at random within the budget constraint. During the double auction process, the customers will dynamically adjust their bid/ask prices based on matching results of previous bids/asks."},{"evidence_id":"v141-b-g04-E04","location":{"location_id":"src-212077b9a1-p15-c1r2__v141-a-M01-bidding","page":15,"printed_page":null,"section":"Appendix B","anchor_text":"Appendix B The bidding process of customers in the continuous double auction (CDA) The bidding proce","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-15.png","occurrence_role":"formula"},"source_text":"The bidding process of customers in the CDA process\n1: while the current time is within the Agreement Period for CDA\n2: if a bid/ask associated with the time slot t arrives at the exchange\n3: run the CDA process as shown in Appendix A;\n4: for any bid o_{b,t} in the order book t\n5: if the last matching was successfully made at the price π_t\n6: if π_{b,t} >= π_t\n7: π_{b,t} = π_{b,t} + γ·(p^{retail}_t - π_{b,t});\n8: end if\n9: if it is an ask that arrived\n10: if π_{b,t} \u003c= π_t\n11: π_{b,t} = π_{b,t} - γ·(π_{b,t} - p^{FiT}_t);\n12: end if\n13: end if\n14: else\n15: if it is a bid that arrived\n16: π_{b,t} = π_{b,t} - γ·(π_{b,t} - p^{FiT}_t);\n17: end if\n18: end if\n19: end for\n20: for any ask o_{s,t} in the order book t\n21: if the last matching was successfully made at the price π_t\n22: if π_{s,t} \u003c= π_t\n23: π_{s,t} = π_{s,t} + γ·(p^{retail}_t - π_{s,t});\n24: end if\n25: if it is a bid that arrived\n26: if π_{s,t} >= π_t\n27: π_{s,t} = π_{s,t} - γ·(π_{s,t} - p^{FiT}_t);\n28: end if\n29: end if\n30: else\n31: if it is an ask that arrived\n32: π_{s,t} = π_{s,t} - γ·(π_{s,t} - p^{FiT}_t);\n33: end if\n34: end if\n35: end for\n36: end if\n37: end while\nNote that γ is the coefficient for customers to update their bid/ask prices, and its value within (0, 1)."},{"evidence_id":"v141-b-g01-E05","location":{"location_id":"src-212077b9a1-p04-c1r2__v141-a-M01-bidding","page":4,"printed_page":null,"section":null,"anchor_text":"Fig. 2. The timeline for ancillary service provision As presented in Section 2, customers trade ener","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"A bid, which is submitted by a buyer, is represented by o_{b,t}(b_t, π_{b,t}, σ_{b,t}, τ_{b,t}), which means that the buyer b_t would like to by the σ_{b,t} (kWh) amount of electricity at the price π_{b,t} (£/kWh), and the bid arrives at the ‘exchange’ at the time τ_{b,t}. Note that the exchange is a centralized or decentralized platform set for P2P energy trading within the community. Similarly, an ask, which is submitted by a seller is represented by o_{s,t}(s_t, π_{s,t}, σ_{s,t}, τ_{s,t})."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding"],"extras":{"decision_anchor":"coordination.price_signal","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E15","quote":"During the double auction process, the customers will dynamically adjust their bid/ask prices based on matching results of previous bids/asks."}],[{"evidence_id":"v141-b-g04-E04","quote":"5: if the last matching was successfully made at the price π_t\n6: if π_{b,t} >= π_t\n7: π_{b,t} = π_{b,t} + γ·(p^{retail}_t - π_{b,t});"},{"evidence_id":"v141-b-g04-E04","quote":"21: if the last matching was successfully made at the price π_t\n22: if π_{s,t} \u003c= π_t\n23: π_{s,t} = π_{s,t} + γ·(p^{retail}_t - π_{s,t});"}],[{"evidence_id":"v141-b-g04-E04","quote":"5: if the last matching was successfully made at the price π_t"},{"evidence_id":"v141-b-g04-E04","quote":"9: if it is an ask that arrived\n10: if π_{b,t} \u003c= π_t\n11: π_{b,t} = π_{b,t} - γ·(π_{b,t} - p^{FiT}_t);\n12: end if\n13: end if"}],[{"evidence_id":"v141-b-g04-E04","quote":"20: for any ask o_{s,t} in the order book t\n21: if the last matching was successfully made at the price π_t"},{"evidence_id":"v141-b-g04-E04","quote":"30: else\n31: if it is an ask that arrived\n32: π_{s,t} = π_{s,t} - γ·(π_{s,t} - p^{FiT}_t);\n33: end if\n34: end if"}],[{"evidence_id":"v141-b-g04-E04","quote":"21: if the last matching was successfully made at the price π_t"},{"evidence_id":"v141-b-g04-E04","quote":"25: if it is a bid that arrived\n26: if π_{s,t} >= π_t\n27: π_{s,t} = π_{s,t} - γ·(π_{s,t} - p^{FiT}_t);\n28: end if\n29: end if"}],[{"evidence_id":"v141-b-g04-E04","quote":"4: for any bid o_{b,t} in the order book t\n5: if the last matching was successfully made at the price π_t"},{"evidence_id":"v141-b-g04-E04","quote":"14: else\n15: if it is a bid that arrived\n16: π_{b,t} = π_{b,t} - γ·(π_{b,t} - p^{FiT}_t);\n17: end if\n18: end if"}]],"C2_formalization":{"graph_sha256":"50df4a8128e557064485edf9aa9bf8684c46ce48ee9d3ed4b163d323b5fc94d6","applicability":"formalized","reason":"Appendix B supplies explicit ZIP price-update equations for the four frozen downward-revision branches. C003-C006 are formalized as conditional assignments using the bid/ask price variables and source parameters gamma, feed-in tariff, and last successful matching price. C001 and C002 remain not_formalized because they state matching-feedback and comparison-reference roles without a standalone source equation. B evidence remains unreviewed under the experiment policy; no independent source audit or scientific acceptance is claimed.","bindings":[{"object_id":"v141-c-R005-x-pi-b","node_ids":["coordination.price_signal","bidding.demand","bidding.supply"],"edge_ids":["v141-c-R005-E001","v141-c-R005-E002"],"rationale":"π_{b,t} is a demand-side bid price updated under coordination.price_signal; E001 links the price signal to demand-side bid behavior, and E002 records the ask-arrival branch in C003 that also conditions bid-price revision."},{"object_id":"v141-c-R005-x-pi-s","node_ids":["coordination.price_signal","bidding.supply","bidding.demand"],"edge_ids":["v141-c-R005-E002","v141-c-R005-E001"],"rationale":"π_{s,t} is a supply-side ask price updated under coordination.price_signal; E002 links the price signal to supply-side ask behavior, and E001 records the bid-arrival branch in C005 that also conditions ask-price revision."},{"object_id":"v141-c-R005-theta-gamma","node_ids":["coordination.price_signal"],"edge_ids":["v141-c-R005-E001","v141-c-R005-E002"],"rationale":"γ scales the downward bid/ask revisions formalized in C003-C006 under the coordination.price_signal node."},{"object_id":"v141-c-R005-theta-p-fit","node_ids":["coordination.price_signal"],"edge_ids":["v141-c-R005-E001","v141-c-R005-E002"],"rationale":"The feed-in tariff p_t^{FiT} is the reference target in the demand-side and supply-side downward price revisions on E001 and E002."},{"object_id":"v141-c-R005-theta-pi-t","node_ids":["matching.counterparties","coordination.price_signal"],"edge_ids":["v141-c-R005-E003","v141-c-R005-E001","v141-c-R005-E002"],"rationale":"π_t is the last successful matching price; E003 links matching results to the price signal, and E001/E002 carry the conditional price updates that compare against π_t."},{"object_id":"v141-c-R005-C001","node_ids":["matching.counterparties","coordination.price_signal"],"edge_ids":["v141-c-R005-E003"],"rationale":"C001 is the frozen matching-feedback relation represented by E003, linking matching.counterparties to coordination.price_signal."},{"object_id":"v141-c-R005-C002","node_ids":["pricing.local","coordination.price_signal"],"edge_ids":["v141-c-R005-E004"],"rationale":"C002 is the frozen relation by which the successful local trading price is used as a comparison reference by coordination.price_signal, represented by E004."},{"object_id":"v141-c-R005-C003","node_ids":["coordination.price_signal","bidding.supply"],"edge_ids":["v141-c-R005-E002"],"rationale":"C003's ask-arrival branch is the condition listed on E002; the expression updates the bid price toward the feed-in tariff reference."},{"object_id":"v141-c-R005-C004","node_ids":["coordination.price_signal","bidding.supply"],"edge_ids":["v141-c-R005-E002"],"rationale":"C004's unsuccessful ask-arrival branch is listed on E002; the expression updates the ask price toward the feed-in tariff reference."},{"object_id":"v141-c-R005-C005","node_ids":["coordination.price_signal","bidding.demand"],"edge_ids":["v141-c-R005-E001"],"rationale":"C005's bid-arrival branch is listed on E001; the expression updates the ask price toward the feed-in tariff reference after comparison with π_t."},{"object_id":"v141-c-R005-C006","node_ids":["coordination.price_signal","bidding.demand"],"edge_ids":["v141-c-R005-E001"],"rationale":"C006's unsuccessful bid-arrival branch is listed on E001; the expression updates the bid price toward the feed-in tariff reference."}],"revision_requests":[]},"C2_delivery":{"raw_sha256":"c67687ccf2e800f7d9d7d5fe420641069571a2ebdf6dc38ba119532f11c5b435","delivery_payload_sha256":"577042496a3297fbc298fc55b48fee79d99e008856a1e4f7cfa0ae2fe5b05921","changes":[{"path":"theta.1.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.2.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."}],"scientific_fields_unchanged":true,"request_graph_sha256":"50df4a8128e557064485edf9aa9bf8684c46ce48ee9d3ed4b163d323b5fc94d6","scientific_correctness_verified":false}},"quarantined_references":[]}});
